#include <iostream>
#include <vector>
#include <map>
#include <set>
using namespace std;

const int MOD = 1000000007;

struct ModularNumber {
    long long value;

    ModularNumber(long long v = 0) {
        value = v % MOD;
        if (value < 0) value += MOD;
    }

    static long long modInverse(long long a, long long m = MOD) {
        long long g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            long long q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return (int)value; }

    ModularNumber& operator+=(const ModularNumber& other) {
        value += other.value;
        if (value >= MOD) value -= MOD;
        return *this;
    }

    ModularNumber& operator-=(const ModularNumber& other) {
        value -= other.value;
        if (value < 0) value += MOD;
        return *this;
    }

    ModularNumber& operator*=(const ModularNumber& other) {
        value = (value * other.value) % MOD;
        return *this;
    }

    ModularNumber& operator/=(const ModularNumber& other) {
        return *this *= ModularNumber(modInverse(other.value));
    }

    friend ModularNumber operator+(const ModularNumber& a, const ModularNumber& b) { return ModularNumber(a) += b; }
    friend ModularNumber operator-(const ModularNumber& a, const ModularNumber& b) { return ModularNumber(a) -= b; }
    friend ModularNumber operator*(const ModularNumber& a, const ModularNumber& b) { return ModularNumber(a) *= b; }
    friend ModularNumber operator/(const ModularNumber& a, const ModularNumber& b) { return ModularNumber(a) /= b; }

    ModularNumber& operator++() {
        value = (value == MOD - 1) ? 0 : value + 1;
        return *this;
    }

    ModularNumber& operator--() {
        value = (value == 0) ? MOD - 1 : value - 1;
        return *this;
    }

    ModularNumber operator++(int) { ModularNumber tmp = *this; ++(*this); return tmp; }
    ModularNumber operator--(int) { ModularNumber tmp = *this; --(*this); return tmp; }

    ModularNumber operator-() const {
        return value == 0 ? 0 : MOD - value;
    }

    bool operator==(const ModularNumber& other) const { return value == other.value; }
    bool operator!=(const ModularNumber& other) const { return value != other.value; }

    ModularNumber inv() const {
        return ModularNumber(modInverse(value));
    }

    ModularNumber pow(long long p) const {
        ModularNumber base = *this, result = 1;
        while (p > 0) {
            if (p & 1) result *= base;
            base *= base;
            p >>= 1;
        }
        return result;
    }
};

int main() {
    int N;
    cin >> N;
    vector<vector<ModularNumber>> prob(N, vector<ModularNumber>(N));
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            int p;
            cin >> p;
            prob[i][j] = ModularNumber(p) / ModularNumber(100);
        }

    vector<vector<int>> count_by_popcount(N + 1);
    vector<int> lookup(1 << N, -1);
    for (int m = 0; m < (1 << N); ++m) {
        int c = __builtin_popcount(m);
        lookup[m] = (int)count_by_popcount[c].size();
        count_by_popcount[c].push_back(m);
    }

    map<long long, ModularNumber> current_states;
    current_states[1LL << lookup[0]] = 1;

    for (int layer = 0; layer < N; ++layer) {
        map<long long, ModularNumber> next_states;
        for (int mask = 0; mask < (1 << N); ++mask) {
            ModularNumber prod = 1;
            for (int r = 0; r < N; ++r) {
                bool bit_set = (mask >> r) & 1;
                prod *= bit_set ? prob[layer][r] : (ModularNumber(1) - prob[layer][r]);
            }
            for (auto& p : current_states) {
                long long msk = p.first;
                ModularNumber pval = p.second;
                long long new_msk = 0;
                for (int m : count_by_popcount[layer]) {
                    if ((msk >> lookup[m]) & 1) {
                        for (int i = 0; i < N; ++i) {
                            if (((mask >> i) & 1) && ((m >> i) & 1) == 0) {
                                new_msk |= 1LL << lookup[m | (1 << i)];
                            }
                        }
                    }
                }
                next_states[new_msk] += pval * prod;
            }
        }
        current_states = move(next_states);
    }

    ModularNumber total = 0;
    int last_idx = lookup[(1 << N) - 1];
    for (auto& p : current_states) {
        if ((p.first >> last_idx) & 1) total += p.second;
    }
    cout << (int)total << "\n";
}
